const raw = $input.first().json.data || $input.first().json.body || '';
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);

const items = [];
// Pontos egyezés a küldött fájl struktúrájára
const regex = /<a\s+id="([^"]+)"\s+href="([^"]+)">([^<]+)<\/a>/g;
let match;
let counter = 1;

while ((match = regex.exec(text)) !== null) {
  items.push({
    json: {
      DBID: counter++,
      id: match[1],
      href: match[2],
      linktext: match[3].trim()
    }
  });
}

return items;

const items = $input.all();
const results = [];

function clean(str) {
  if (!str) return '';
  return str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

for (let i = 0; i < items.length; i++) {
  const rawHtml = items[i].json.data || items[i].json.body || '';
  const rowObj = {};

  // 1. Edikt blokk szűrése
  const ediktMatch = rawHtml.match(/<div[^>]*id=["']edikt["'][^>]*>([\s\S]*?)<\/div>/i);
  const content = ediktMatch ? ediktMatch[1] : rawHtml;

  // 2. h1 és h2 fejléc mezők kinyerése
  const h1Match = content.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  const h2Match = content.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
  rowObj['h1'] = h1Match ? clean(h1Match[1]) : '';
  rowObj['h2'] = h2Match ? clean(h2Match[1]) : '';

  // 3. Mezőpárok: span (title) és p (value)
  const rowRegex = /<div[^>]*class=["'][^"']*row[^"']*["'][^>]*>([\s\S]*?)<\/div>/gi;
  let rMatch;

  while ((rMatch = rowRegex.exec(content)) !== null) {
    const rowInner = rMatch[1];
    const span = rowInner.match(/<span[^>]*class=["'][^"']*col-sm-3[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
    const p = rowInner.match(/<p[^>]*class=["'][^"']*col-sm-9[^"']*["'][^>]*>([\s\S]*?)<\/p>/i);

    if (span && p) {
      const key = clean(span[1]).replace(/[:]+$/, '');
      const val = clean(p[1]);
      if (key) {
        rowObj[key] = val;
      }
    }
  }

  results.push({ json: rowObj });
}

return results;
